const updateMenu = `-- name: UpdateMenu :one
UPDATE menus
SET parent_id = $2,
    type = $3,
    title = $4,
    path = $5,
    icon = $6,
    permission_code = $7,
    sort_order = $8,
    visible = $9,
    status = $10,
    updated_by = $11,
    updated_at = now()
WHERE id = $1
RETURNING
    id,
    parent_id,
    type,
    code,
    title,
    title_key,
    path,
    icon,
    permission_code,
    sort_order,
    visible,
    status,
    is_system,
    created_by,
    updated_by,
    created_at,
    updated_at
`

